using System.Data; using CertDesk.Common; using CertDesk.Models; using CertDesk.Services;
namespace CertDesk.Views;
public partial class DashboardView:UserControl{ readonly DataGridView grid=new(); public DashboardView(CurrentUser u){InitializeComponent(); Build(); LoadData();} void Build(){BackColor=UiTheme.Light; var panel=new FlowLayoutPanel{Dock=DockStyle.Top,Height=120,Padding=new Padding(15)}; for(int i=0;i<7;i++) panel.Controls.Add(new Label{Name="card"+i,Width=155,Height=80,BackColor=Color.White,TextAlign=ContentAlignment.MiddleCenter,Font=new Font("Segoe UI",10,FontStyle.Bold)}); var btn=new Button{Text="Обновить",Left=15,Top=130,Width=120}; UiTheme.ApplyButtonStyle(btn); grid.Top=175;grid.Left=15;grid.Width=900;grid.Height=420;grid.Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right|AnchorStyles.Bottom;UiTheme.ApplyGridStyle(grid); Controls.AddRange(new Control[]{panel,btn,grid}); btn.Click+=(_,__)=>LoadData();} void LoadData(){ var cards=Controls.OfType<FlowLayoutPanel>().First().Controls.OfType<Label>().ToArray(); cards[0].Text=$"Действующие сертификаты\n{CertificateService.CountByStatus("active")}";cards[1].Text=$"Истекающие сертификаты\n{CertificateService.CountByStatus("warning")}";cards[2].Text=$"Действующие МЧД\n{MchdService.CountByStatus("active")}";cards[3].Text=$"Истекающие МЧД\n{MchdService.CountByStatus("warning")}";cards[4].Text=$"Всего токенов\n{TokenService.CountAll()}";cards[5].Text=$"Выданные токены\n{TokenService.CountIssued()}";cards[6].Text=$"Активные сотрудники\n{EmployeeService.GetActive().Count}"; var t=CertificateService.GetAttentionItems(); t.Merge(MchdService.GetAttentionItems()); grid.DataSource=t;} }
